    var SUBTITLE_COUNT  = 6;
    var events          = [{"ms": 1606780800000, "date": "2020-12-01", "label": "Beacon chain genesis", "desc": "The beacon chain launched. It ran alongside the original proof-of-work chain and did not secure execution or allow withdrawals. It gave early stakers rewards in the expectation that Ethereum would in future complete its migration to proof of stake."}, {"ms": 1619136000000, "date": "2021-04-23", "label": "Paradigm on Staking Derivatives", "desc": "In their article, Hasu and Georgios Konstantopoulos argued that, because of the existance of staking derivatives, the staking participation rate could reach 80-100%."}, {"ms": 1646006400000, "date": "2022-02-28", "label": "stETH allowed as collateral on AAVE", "desc": "The availability of Lido staked Ether (stETH) as lending collateral on AAVE allowed for a \"looping\" strategy, using stETH to borrow Ether to be staked for more stETH (etc)."}, {"ms": 1653004800000, "date": "2022-05-20", "label": "Danny Ryan: \"The Risks of LSD\"", "desc": "Danny Ryan published an article highlighting concerns that liquid staking services, such as Lido (which held almost 33% of all staked ETH at the time), would pose a threat to Ethereum's consensus model if they grew too large."}, {"ms": 1663200000000, "date": "2022-09-15", "label": "The Merge", "desc": "Ethereum's proof-of-work era came to an end as the execution layer and proof-of-stake consensus layer were merged."}, {"ms": 1675900800000, "date": "2023-02-09", "label": "SEC vs Kraken", "desc": "The SEC settled with Kraken, after complaining Kraken's staking service entailed sales of unregistered securities. Kraken was to end the service and pay $30m. Kraken's stake constituted most of the ETH withdrawn immediately after the Shapella upgrade."}, {"ms": 1681257600000, "date": "2023-04-12", "label": "Shapella upgrade", "desc": "Ethereum's Shapella upgrade allowed stakers to withdraw their funds from the Consensus Layer back to the Execution Layer. The possibility of withdrawal significantly derisked Ethereum staking, leading to large inflows of new stake."}, {"ms": 1686700800000, "date": "2023-06-14", "label": "Eigenlayer points", "desc": "Eigenlayer announced a points system for restakers which was widely (and correctly) assumed to be a precursor to an airdrop, driving increased staking demand by stakers hoping to be rewarded with future tokens."}, {"ms": 1700524800000, "date": "2023-11-21", "label": "Blast bridge", "desc": "The Blast L2 promised \"native yield\" to its users by staking all ETH deposits, which were accepted for several months prior to its launch in February 2024. By this time Blast had amassed over 600k ETH in deposits."}, {"ms": 1708560000000, "date": "2024-02-22", "label": "Issuance debate", "desc": "Ansgar Dietrichs and Caspar Schwarz-Schilling published articles arguing that Ethereum's issuance policy would lead to an excessive staking ratio, highlighting negative consequences and arguing for a swift issuance reduction."}, {"ms": 1710288000000, "date": "2024-03-13", "label": "Dencun upgrade", "desc": "The Dencun upgrade introduced blobs, promoting a move to L2 blockchains and a reduction in contention for L1 blockspace (resulting in much lower fee burn). Meanwhile, the reduction in churn limit reduced the rate at which the active stake could grow."}, {"ms": 1727740800000, "date": "2024-10-01", "label": "EIGEN unlock", "desc": "The EIGEN token unlock brought an end to airdrop farming, which had stimulated increased staking participation. Some stakers began withdrawing and the staking ratio peaked just afterwards, stagnating until the SEC's revised stance 8 months later."}, {"ms": 1748476800000, "date": "2025-05-29", "label": "SEC staking guidance", "desc": "Reversing its position under the previous administration, the SEC issued guidance that, under certain criteria, staking services did not constitute securities offerings. New stake flooded in. The entry queue has not cleared since this announcement."}, {"ms": 1752796800000, "date": "2025-07-18", "label": "AAVE rate shock", "desc": "A large AAVE withdrawal triggered an ETH lending rate spike, which in turn caused an unwind of looped staking positions."}, {"ms": 1757462400000, "date": "2025-09-10", "label": "Kiln Security Exit", "desc": "A security incident led to the Kiln staking provider withdrawing their entire stake."}, {"ms": 1766793600000, "date": "2025-12-27", "label": "BitMine Begins Staking", "desc": "Major ETH treasury BitMine started staking its Ether leading to further large consensus layer inflows and staking ratios above 30% for the first time."}];
